using System;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
using System.Windows.Forms;
namespace Aster {
partial class ThemePalette {
 public static Color Mix(Color a,Color b,double amount){return Color.FromArgb((int)(a.R*(1-amount)+b.R*amount),(int)(a.G*(1-amount)+b.G*amount),(int)(a.B*(1-amount)+b.B*amount));}
 static ThemePalette[] CreateCollection(){string[] names={"Sapphire","Emerald","Cherry","Lavender","Copper","Iceberg","Moss","Plum","Cocoa","Indigo","Peach","Slate","Jade","Orchid","Sandstone","Arctic","Mulberry","Electric"};int[] hues={0x83b4ff,0x8be1ac,0xff9b9b,0xd5b9ff,0xf4b38d,0xa0e8ff,0xc2d793,0xe4b1e6,0xe5c5a0,0xa9b4ff,0xffc4ae,0xb0c8dc,0x8fe1cf,0xf2afe3,0xe9d3a8,0xbcefe9,0xe6a6c6,0xe5f78e};return Core.Concat(names.Select((name,i)=>{Color accent=C(hues[i]);return new ThemePalette{Id=name.ToLowerInvariant(),Name=name,Description="Coordinated dark palette · "+name,Background=Mix(Color.FromArgb(14,16,22),accent,.05),Surface=Mix(Color.FromArgb(19,22,29),accent,.10),Raised=Mix(Color.FromArgb(22,26,34),accent,.16),Sidebar=Mix(Color.FromArgb(15,18,24),accent,.08),Border=Mix(Color.FromArgb(35,41,52),accent,.25),Accent=accent,Hero=Mix(Color.FromArgb(24,28,38),accent,.25)};})).ToArray();}
}
class ThemeRecipe {public int Version=1;public string Background="#171925",Accent="#BCA4FF";}
static class CustomTheme {
 public static Color Parse(string value){if(value==null||value.Length!=7||value[0]!='#')throw new Exception("Use six-digit colors such as #171925.");int n;if(!int.TryParse(value.Substring(1),NumberStyles.HexNumber,CultureInfo.InvariantCulture,out n))throw new Exception("Invalid hexadecimal color.");return Color.FromArgb(n>>16,(n>>8)&255,n&255);}
 static double Channel(byte x){double v=x/255.0;return v<=.04045?v/12.92:Math.Pow((v+.055)/1.055,2.4);}
 public static double Luminance(Color c){return .2126*Channel(c.R)+.7152*Channel(c.G)+.0722*Channel(c.B);}
 public static double Contrast(Color a,Color b){double x=Luminance(a),y=Luminance(b);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
 public static ThemePalette Create(ThemeRecipe r){if(r==null||r.Version!=1)throw new Exception("Unsupported theme recipe.");Color bg=Parse(r.Background),accent=Parse(r.Accent);var t=new ThemePalette{Id="custom",Name="Your custom theme",Description="Made in Aster Theme studio",Background=bg,Surface=ThemePalette.Mix(bg,Color.White,.035),Raised=ThemePalette.Mix(bg,Color.White,.07),Sidebar=ThemePalette.Mix(bg,Color.Black,.12),Border=ThemePalette.Mix(bg,Color.White,.20),Hero=ThemePalette.Mix(bg,accent,.18),Accent=accent};if(Contrast(t.Text,t.Raised)<4.5||Contrast(t.Muted,t.Raised)<4.5)throw new Exception("Choose a darker background so the text stays readable.");if(Contrast(accent,t.Raised)<3||Contrast(accent,t.Hero)<3)throw new Exception("Choose a brighter accent so highlights stay visible.");return t;}
 public static ThemeRecipe Read(string path){if(new FileInfo(path).Length>8192)throw new Exception("Theme recipes must be smaller than 8 KB.");var r=new JavaScriptSerializer{MaxJsonLength=8192}.Deserialize<ThemeRecipe>(File.ReadAllText(path));Create(r);return r;}
}
partial class MainWindow {
 ThemePalette ResolveTheme(){if(preferences.ThemeId=="custom"){try{return CustomTheme.Create(new ThemeRecipe{Background=preferences.CustomBase,Accent=preferences.CustomAccent});}catch{return ThemePalette.Find("midnight");}}return ThemePalette.Find(preferences.ThemeId);}
 void BuildThemeGallery(){sub.Text=ThemePalette.All.Length+" ready-made themes · search, apply, or create your own";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(root);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};var filter=new TextBox{Width=260,Margin=new Padding(0,6,12,0)};actions.Controls.Add(new Label{Text="Find a theme",AutoSize=true,Margin=new Padding(0,9,10,0)});actions.Controls.Add(filter);var create=Button("Open Theme studio →");create.Click+=(s,e)=>Navigate("Theme studio");actions.Controls.Add(create);root.Controls.Add(actions,0,0);var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};root.Controls.Add(scroll,0,1);var flow=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};scroll.Controls.Add(flow);foreach(var palette in ThemePalette.All){var p=palette;var card=new ThemeCard{Palette=p,Selected=p.Id==preferences.ThemeId,AccessibleName="Apply "+p.Name,Text=p.Name};card.Click+=(s,e)=>{string previous=preferences.ThemeId;preferences.ThemeId=p.Id;if(!SavePreferences()){preferences.ThemeId=previous;return;}ApplyAppTheme();foreach(ThemeCard c in flow.Controls.OfType<ThemeCard>()){c.Selected=c.Palette.Id==preferences.ThemeId;c.Invalidate();}};flow.Controls.Add(card);}var noMatch=new Label{Text="No matching theme. Try a shorter name.",AutoSize=true,Visible=false};flow.Controls.Add(noMatch);filter.TextChanged+=(s,e)=>{int count=0;foreach(ThemeCard c in flow.Controls.OfType<ThemeCard>()){c.Visible=c.Palette.Name.IndexOf(filter.Text.Trim(),StringComparison.OrdinalIgnoreCase)>=0;if(c.Visible)count++;}noMatch.Visible=count==0;};}
 void BuildThemeStudio(){sub.Text="Create a coordinated dark theme · preview first · import or export a color recipe";var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,WrapContents=false,FlowDirection=FlowDirection.TopDown,Padding=new Padding(12)};content.Controls.Add(flow);flow.Controls.Add(new Label{Text="Make it yours.",AutoSize=true,Font=new Font("Segoe UI",25,FontStyle.Bold)});var bgBox=new TextBox{Text=preferences.CustomBase,Width=150};var accentBox=new TextBox{Text=preferences.CustomAccent,Width=150};foreach(var pair in new[]{Tuple.Create("Background",bgBox),Tuple.Create("Accent",accentBox)}){var row=new FlowLayoutPanel{Width=580,Height=44};row.Controls.Add(new Label{Text=pair.Item1,Width=120,Margin=new Padding(0,8,0,0)});row.Controls.Add(pair.Item2);var edit=pair.Item2;var picker=Button("Pick color");picker.Click+=(s,e)=>{using(var d=new ColorDialog{FullOpen=true}){try{d.Color=CustomTheme.Parse(edit.Text);}catch{}if(d.ShowDialog(this)==DialogResult.OK)edit.Text="#"+d.Color.R.ToString("X2")+d.Color.G.ToString("X2")+d.Color.B.ToString("X2");}};row.Controls.Add(picker);flow.Controls.Add(row);}var preview=new ThemeCard{Palette=ResolveTheme(),Enabled=false};flow.Controls.Add(preview);var result=new Label{AutoSize=true,MaximumSize=new Size(720,0),Text="Enter a dark background and bright accent. Preview checks text/highlight contrast."};flow.Controls.Add(result);Func<ThemeRecipe> recipe=()=>new ThemeRecipe{Background=bgBox.Text.Trim(),Accent=accentBox.Text.Trim()};Action<Action> guard=action=>{try{action();}catch(Exception ex){result.Text=ex.Message;}};var actions=new FlowLayoutPanel{Width=760,Height=90};flow.Controls.Add(actions);var test=Button("Preview");test.Click+=(s,e)=>guard(()=>{preview.Palette=CustomTheme.Create(recipe());preview.Invalidate();result.Text="Preview ready. Your current theme has not changed.";});actions.Controls.Add(test);var apply=Button("Apply & save");apply.Click+=(s,e)=>guard(()=>{var r=recipe();preview.Palette=CustomTheme.Create(r);string oldBase=preferences.CustomBase,oldAccent=preferences.CustomAccent,oldId=preferences.ThemeId;preferences.CustomBase=r.Background;preferences.CustomAccent=r.Accent;preferences.ThemeId="custom";if(!SavePreferences()){preferences.CustomBase=oldBase;preferences.CustomAccent=oldAccent;preferences.ThemeId=oldId;result.Text="Theme was not saved. Your previous theme is still active.";return;}ApplyAppTheme();result.Text="Custom theme applied and saved.";preview.Invalidate();});actions.Controls.Add(apply);var export=Button("Export recipe");export.Click+=(s,e)=>guard(()=>{var r=recipe();CustomTheme.Create(r);using(var d=new SaveFileDialog{Filter="Theme recipe|*.json",FileName="Aster-theme.json"})if(d.ShowDialog(this)==DialogResult.OK){File.WriteAllText(d.FileName,new JavaScriptSerializer().Serialize(r));result.Text="Theme recipe exported.";}});actions.Controls.Add(export);var import=Button("Import recipe");import.Click+=(s,e)=>guard(()=>{using(var d=new OpenFileDialog{Filter="Theme recipe|*.json"})if(d.ShowDialog(this)==DialogResult.OK){var r=CustomTheme.Read(d.FileName);bgBox.Text=r.Background;accentBox.Text=r.Accent;preview.Palette=CustomTheme.Create(r);preview.Invalidate();result.Text="Recipe loaded for preview. Click Apply to use it.";}});actions.Controls.Add(import);}
}
}
